    public static void drawArrow(ru.zov.common.util.entity.EntityStory.CustomEntity customEntity, int size, int radius, int color) {
        if (mc.player == null || customEntity == null || customEntity.entity() == null) {
            return;
        }
        net.minecraft.entity.Entity entity = customEntity.entity();
        double angle = Math.atan2(mc.player.getEntityPos().x - entity.getEntityPos().x, mc.player.getEntityPos().z - entity.getEntityPos().z) + Math.toRadians(mc.gameRenderer.getCamera().getYaw());
        float centerX = mc.getWindow().getScaledWidth() / 2.0F;
        float centerY = mc.getWindow().getScaledHeight() / 2.0F;
        float directionX = (float) Math.sin(angle);
        float directionY = (float) Math.cos(angle);
        float perpendicularX = directionY;
        float perpendicularY = -directionX;
        float x = centerX + directionX * radius;
        float y = centerY + directionY * radius;
        float tipX = x + directionX * size / 2.0F;
        float tipY = y + directionY * size / 2.0F;
        float baseX = x - directionX * size / 2.0F;
        float baseY = y - directionY * size / 2.0F;
        float halfWidth = size * 0.35F;
        float leftX = baseX + perpendicularX * halfWidth;
        float leftY = baseY + perpendicularY * halfWidth;
        float rightX = baseX - perpendicularX * halfWidth;
        float rightY = baseY - perpendicularY * halfWidth;
        int alphaColor = ColorUtil.multAlpha(color, customEntity.animation().getOutput().floatValue());
        drawLine(tipX, tipY, leftX, leftY, 2.0F, alphaColor);
        drawLine(leftX, leftY, rightX, rightY, 2.0F, alphaColor);
        drawLine(rightX, rightY, tipX, tipY, 2.0F, alphaColor);
    }

    public static Identifier getHeadId(net.minecraft.entity.LivingEntity entity) {
        net.minecraft.client.render.entity.EntityRenderer renderer = mc.getEntityRenderDispatcher().getRenderer(entity);
        if (renderer instanceof net.minecraft.client.render.entity.LivingEntityRenderer livingRenderer) {
            net.minecraft.client.render.entity.state.LivingEntityRenderState state = (net.minecraft.client.render.entity.state.LivingEntityRenderState) livingRenderer.getAndUpdateRenderState(entity, tickCounter.getTickProgress(true));
            return livingRenderer.getTexture(state);
        }
        return Identifier.of("minecraft", "textures/entity/steve.png");
    }

